/* THE NIB. Fast is thin, slow pools, and the width eases so
   one quick frame cannot notch the line. */
const v = dist / dt;                          /* px per ms */
const target = thick - (thick - thin) * clamp(v / 1.6, 0, 1);
w += (target - w) * 0.35;

/* each segment is its own curve through the midpoints */
<path d="M{start} Q{point} {mid}" stroke-width={w} />

/* CLEAR REWINDS: un-draw, last point first */
cut = total * (1 - ease(k));
